parameters.query:
SELECT * FROM conversation_turns
WHERE conversation_id = '{{ $json.id }}'::uuid
ORDER BY turn_number ASC;

parameters.functionCode:
// Build complete conversation transcript
const conversation = $('Process in Batches').item.json;
const turns = $('Get Full Transcript').all();

const transcript = turns.map(turn => 
  `${turn.json.speaker.toUpperCase()}: ${turn.json.message}`
).join('\n\n');

return {
  json: {
    conversationId: conversation.id,
    intent: conversation.intent,
    outcome: conversation.outcome,
    satisfaction: conversation.customer_satisfaction,
    agentName: conversation.agent_name,
    turnCount: conversation.turn_count,
    transcript: transcript,
    duration: conversation.duration_seconds,
    wasEscalated: conversation.status === 'escalated'
  }
};

// Extract insights from Claude's analysis
const analysisText = $json.content[0].text;
let insights;

try {
  // Try to parse if Claude returned JSON
  insights = JSON.parse(analysisText);
} catch (e) {
  // Otherwise structure the text response
  insights = {
    summary: analysisText.substring(0, 500),
    raw_analysis: analysisText
  };
}

const conversationData = $('Build Full Transcript').item.json;

return {
  json: {
    conversationId: conversationData.conversationId,
    intent: conversationData.intent,
    insights: insights,
    metadata: {
      outcome: conversationData.outcome,
      satisfaction: conversationData.satisfaction,
      agent: conversationData.agentName,
      duration: conversationData.duration,
      turnCount: conversationData.turnCount,
      wasEscalated: conversationData.wasEscalated,
      analyzed_at: new Date().toISOString()
    }
  }
};

parameters.query:
INSERT INTO quality_reviews (id, conversation_id, review_type, priority, flagged_at, metadata)
VALUES (
  gen_random_uuid(),
  '{{ $json.conversationId }}'::uuid,
  'low_satisfaction',
  'high',
  NOW(),
  '{{ JSON.stringify({ 
    satisfaction: $json.metadata.satisfaction,
    insights: $json.insights.improvements || "Needs review"
  }) }}'::jsonb
);
